mapper.select:


    and template_code like concat('%', #{templateCode}, '%')
    and channel = #{channel}
    and category = #{category}
    and status = #{status}

order by template_code, channel

select count(*) from abr_message_template
where template_code = #{templateCode} and channel = #{channel}
and template_id <> #{templateId}

select send_id, template_code, channel, category, target_type, target_id, recipient, agent_code, task_id, status, reason, platform_msg_id,
       rendered, create_by, create_time
from abr_message_send

    and template_code = #{templateCode}
    and channel = #{channel}
    and status = #{status}
    and target_type = #{targetType}
    and target_id = #{targetId}
    and create_time >= cast(#{params.beginTime} as date)
    and create_time < cast(#{params.endTime} as date) + interval '1 day'

order by send_id desc
